<script setup>
import { computed } from 'vue';import { useDoctorStore } from '../../../stores/doctors';import { useClinicContextStore } from '../../../stores/clinicContext';const store=useDoctorStore(),context=useClinicContextStore();
const groups=computed(()=>[['Personal information',[['Full name',store.doctor.full_name],['Gender',store.doctor.gender],['Doctor number',store.doctor.doctor_number]]],['Professional information',[['Specialties',store.doctor.specialties.map(s=>s.name).join(', ')],['License number',store.doctor.license_number],['Qualification',store.doctor.qualification],['Consultation fee',store.doctor.consultation_fee===null?null:`${context.data.plan?.currency || 'USD'} ${store.doctor.consultation_fee}`]]],['Contact information',[['Phone',store.doctor.phone],['Email',store.doctor.email]]],['Branch assignments',store.doctor.branches.map(b=>[b.id===store.doctor.primary_branch_id?'Primary branch':'Additional branch',b.name])],['Account information',[['Linked user',store.doctor.user?.name],['Account email',store.doctor.user?.email],['Account status',store.doctor.user?.status]]],['Notes',[['Profile notes',store.doctor.notes]]]]);
</script>
<template><div class="patient-overview-grid"><section v-for="[title,fields] in groups" :key="title" class="clinic-panel"><h2 class="font-bold text-base mb-4">{{title}}</h2><dl class="detail-list"><div v-for="([label,value],index) in fields" :key="index"><dt>{{label}}</dt><dd class="break-words whitespace-pre-wrap">{{value || 'Not recorded'}}</dd></div></dl></section><section class="clinic-panel col-span-full"><h2 class="font-bold">Clinical activity</h2><p class="mt-3 text-slate-500">No appointment or consultation statistics are available yet. These will appear when those workflows are introduced.</p></section></div></template>
